const items = $input.all();
const mergedItems = $('Merge Both Paths').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const job = mergedItems[i]?.json || {};
  const raw = (items[i].json.message?.content || '{}').replace(/```json\n?/g, '').replace(/```/g, '').trim();
  const scoreData = JSON.parse(raw);
  const posted = job.posted || '';
  const isUpwork = (job.url || '').includes('upwork.com');
  const isDuration = posted.includes('month') || posted.includes('week');

  // --- Salary scoring (40 points) ---
  const salaryStr = (job.salary || '').replace(/,/g, '');
  let salaryValue = 0;
  let salaryMin = 0;

  const phpMatch = salaryStr.match(/PHP\s*([\d.]+)/i);
  const usdMatch = salaryStr.match(/\$\s*([\d.]+)/g);

  if (phpMatch) {
    const phpAll = salaryStr.match(/[\d.]+/g).map(Number);
    salaryValue = Math.max(...phpAll);
    salaryMin = 70000;
  } else if (usdMatch) {
    const usdAll = salaryStr.match(/[\d.]+/g).map(Number);
    salaryValue = Math.max(...usdAll);
    if (salaryStr.toLowerCase().includes('fixed') || (!salaryStr.includes('/hr') && !salaryStr.includes('hour') &&
!salaryStr.includes('-') && isUpwork)) {
      salaryMin = 500;
    } else {
      salaryMin = 15;
    }
  }

  let salaryScore = 10;
  if (salaryMin > 0 && salaryValue > 0) {
    if (salaryValue >= salaryMin * 2) {
      salaryScore = 40;
    } else if (salaryValue >= salaryMin) {
      salaryScore = 20 + Math.round(((salaryValue - salaryMin) / salaryMin) * 20);
    } else {
      salaryScore = Math.round((salaryValue / salaryMin) * 20);
    }
  }

  const skillsScore = scoreData.skills_score || 0;
  const experienceScore = scoreData.experience_score || 0;
  const totalScore = skillsScore + experienceScore + salaryScore;

  results.push({ json: {
    timestamp: $('Gmail Trigger').first().json.date || new Date().toLocaleString('en-PH', { timeZone: 'Asia/Manila'
}),
    source: job.source || 'N/A',
    job_title: job.title || 'N/A',
    company: job.company || 'N/A',
    location: job.location || 'N/A',
    remote: (job.remote || (job.url || '').includes('upwork.com')) ? 'Yes' : 'No',
    salary: job.salary || 'N/A',
    skills_required: (job.skills_required || []).length ? job.skills_required.join(', ') : 'N/A',
    job_type: job.job_type || 'N/A',
    experience_level: job.experience_level || 'N/A',
    duration: (isUpwork && isDuration) ? posted : (job.duration || 'N/A'),
    url: job.job_url || job.url || 'N/A',
    description_summary: job.description_summary || 'N/A',
    score: totalScore,
    skill_match: skillsScore + '/30',
    experience_fit: experienceScore + '/30',
    interest_fit: salaryScore + '/40',
    matching_skills: (scoreData.matching_skills || []).length ? scoreData.matching_skills.join(', ') : 'N/A',
    missing_skills: (scoreData.missing_skills || []).length ? scoreData.missing_skills.join(', ') : 'N/A',
    reasoning: scoreData.reasoning || 'N/A',
    status: 'new',
    reported_at: new Date().toLocaleString('en-PH', { timeZone: 'Asia/Manila' })
  }});
}

return results;

const from = ($json.from?.text || $json.From || '').toLowerCase();
const subject = ($json.subject || $json.Subject || '').toLowerCase();

const knownSenders = {
  'upwork.com': 'upwork',
  'jobstreet.com': 'jobstreet',
  'indeed.com': 'indeed',
  'linkedin.com': 'linkedin',
  'glassdoor.com': 'glassdoor',
  'monster.com': 'monster',
  'ziprecruiter.com': 'ziprecruiter',
  'onlinejobs.ph': 'onlinejobs_ph',
  'virtualstaff.ph': 'virtualstaff_ph',
  'remotive.com': 'remotive',
  'weworkremotely.com': 'weworkremotely'
};

let source = 'unknown';
let isJobEmail = false;

for (const [domain, name] of Object.entries(knownSenders)) {
  if (from.includes(domain)) {
    source = name;
    isJobEmail = true;
    break;
  }
}

if (!isJobEmail) {
  const jobKeywords = ['new job', 'job alert', 'job match', 'job recommendation',
    'we found', 'jobs for you', 'hiring', 'job opportunity', 'apply now',
    'career', 'position', 'vacancy', 'openings for you'];
  if (jobKeywords.some(kw => subject.includes(kw))) {
    isJobEmail = true;
    source = 'other';
  }
}

return [{ json: { ...$json, is_job_email: isJobEmail, source } }];

const text = $json.text || $json.textPlain || $json.snippet || '';
const source = 'indeed';

const lines = text.split('\n').filter(l => l.trim());
const jobs = [];
let currentJob = null;

for (const line of lines) {
  const trimmed = line.trim();

  if (trimmed.startsWith('Indeed Job Alert') || trimmed.startsWith('Jobs 1-') ||
      trimmed.startsWith('See matching') || trimmed.startsWith('Do not share') ||
      trimmed.startsWith('Salaries estimated') || trimmed.startsWith('©') ||
      trimmed.startsWith('Privacy') || trimmed.startsWith('Terms') ||
      trimmed.startsWith('Help Center') || trimmed.startsWith('Manage email') ||
      trimmed.startsWith('Unsubscribe') || trimmed.startsWith('View all') ||
      trimmed.startsWith('View jobs') || trimmed.includes('Indeed Ireland') ||
      trimmed.includes('Block B, Capital') ||
      /^\d+ new .+ jobs? in /i.test(trimmed) ||
      trimmed === 'These job ads match your saved job alert ¹' ||
      trimmed.startsWith('Indeed homepage') ||
      trimmed.startsWith('see messages') ||
      trimmed.startsWith('see notifications')) continue;

  if (trimmed.startsWith('https://')) {
    if (currentJob) {
      currentJob.url = trimmed;
      jobs.push(currentJob);
      currentJob = null;
    }
    continue;
  }

  if (trimmed === 'Easily apply' || trimmed === 'Responsive employer') continue;

  if (/^\d+ days? ago$|^Just posted$/.test(trimmed)) {
    if (currentJob) currentJob.posted = trimmed;
    continue;
  }

  if (trimmed.startsWith('PHP ') || trimmed.match(/^PHP \d/)) {
    if (currentJob) currentJob.salary = trimmed;
    continue;
  }

  if (!currentJob) {
    currentJob = { title: trimmed, company: '', location: '', salary: '', description: '', posted: '', url: '', source
 };
    continue;
  }

  if (!currentJob.company) {
    const parts = trimmed.split(' - ');
    currentJob.company = parts[0] || '';
    currentJob.location = parts.slice(1).join(' - ') || '';
    continue;
  }

  if (currentJob.description) {
    currentJob.description += ' ' + trimmed;
  } else {
    currentJob.description = trimmed;
  }
}

return jobs.map(j => ({ json: j }));

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenJobs) staticData.seenJobs = {};

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const key = `${(job.title || '')}::${(job.company || '')}`.toLowerCase().trim();

  if (!staticData.seenJobs[key]) {
    staticData.seenJobs[key] = Date.now();
    results.push(item);
  }
}

const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
for (const [k, v] of Object.entries(staticData.seenJobs)) {
  if (v < thirtyDaysAgo) delete staticData.seenJobs[k];
}

return results;
